## 问题 1：权限授权后扫描不自动开始

### 1. `device_search_controller.dart` 全文

`DeviceSearchState` 与 `DeviceSearchController` 均在同一文件，无独立 model 文件。

```1:185:packages/feature/device/feature_device_search/lib/src/controller/device_search_controller.dart
import 'dart:async';

import 'package:core_ble/core_ble.dart';
import 'package:core_permission/core_permission.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../provider/device_name_filter_provider.dart';
import '../provider/device_search_providers.dart';

/// Delay between short platform scan windows while the search page is open.
final deviceSearchRestartDelayProvider = Provider<Duration>(
  (_) => const Duration(milliseconds: 300),
);

/// Immutable BLE scan UI state.
class DeviceSearchState {
  /// Creates device search state.
  const DeviceSearchState({
    this.devices = const [],
    this.scanning = false,
    this.scanEnded = false,
    this.errorMessage,
  });

  /// Discovered devices, newest unique id wins on update.
  final List<BleDevice> devices;

  /// Whether a scan is in progress.
  final bool scanning;

  /// Whether the current scan window has finished (native rescan affordance).
  final bool scanEnded;

  /// User-visible error, if any.
  final String? errorMessage;

  /// Returns a copy with selective overrides.
  DeviceSearchState copyWith({
    List<BleDevice>? devices,
    bool? scanning,
    bool? scanEnded,
    String? errorMessage,
    bool clearError = false,
  }) {
    return DeviceSearchState(
      devices: devices ?? this.devices,
      scanning: scanning ?? this.scanning,
      scanEnded: scanEnded ?? this.scanEnded,
      errorMessage: clearError ? null : (errorMessage ?? this.errorMessage),
    );
  }
}

/// Controls BLE scan lifecycle for [DeviceSearchPage].
class DeviceSearchController extends Notifier<DeviceSearchState> {
  StreamSubscription<BleDevice>? _scanSubscription;
  var _keepScanning = false;
  var _scanGeneration = 0;

  @override
  DeviceSearchState build() {
    ref.onDispose(() {
      _keepScanning = false;
      _scanSubscription?.cancel();
    });
    Future.microtask(startScan);
    return const DeviceSearchState();
  }

  /// Starts scanning after permissions and adapter checks.
  Future<void> startScan() async {
    // Cancel any in-flight scan without emitting scanEnded — that flag means
    // "a scan pass finished empty/complete", not "cancelled to restart".
    await _cancelActiveScan();
    _keepScanning = true;
    final generation = ++_scanGeneration;
    state = state.copyWith(
      devices: [],
      scanning: true,
      scanEnded: false,
      clearError: true,
    );
    await _scanOnce(clearDevices: false, generation: generation);
  }

  Future<void> _scanOnce({
    required bool clearDevices,
    required int generation,
  }) async {
    final permissions = ref.read(permissionServiceProvider);
    final permissionResult = await BlePermissionGate.ensureScanPermissions(
      permissions,
    );
    if (permissionResult case Failure(:final error)) {
      _keepScanning = false;
      state = state.copyWith(scanning: false, errorMessage: error.message);
      return;
    }

    final ble = ref.read(bleServiceProvider);

    // Fetch the server name allowlist concurrently with the BT availability
    // check. Empty set = API unavailable → show all devices (graceful fallback).
    final (availableResult, nameFilter) = await (
      ble.isAvailable(),
      ref.read(deviceNameFilterProvider.future),
    ).wait;

    // ponytail: error strings are platform-sourced English; l10n upgrade path is
    // moving these into DeviceSearchL10n ARBs and passing l10n into the controller.
    final unavailableMessage = availableResult.fold(
      onSuccess: (on) => on ? null : 'Bluetooth is off or unavailable',
      onFailure: (error) => error.message,
    );
    if (unavailableMessage != null) {
      _keepScanning = false;
      state = state.copyWith(scanning: false, errorMessage: unavailableMessage);
      return;
    }

    state = state.copyWith(
      devices: clearDevices ? [] : state.devices,
      scanning: true,
      clearError: true,
    );
    _scanSubscription = ble
        .scan(timeout: const Duration(seconds: 10))
        .listen(
          (device) {
            // Unnamed devices (name broadcasts empty) are never our glasses.
            if (device.name.isEmpty) return;

            if (!_passesNameFilter(device.name, nameFilter)) return;
            ref.read(onDeviceDiscoveredProvider)?.call(device);
            final devices = [...state.devices];
            final index = devices.indexWhere((item) => item.id == device.id);
            if (index >= 0) {
              if (devices[index].rssi == device.rssi) return;
              devices[index] = device;
            } else {
              devices.add(device);
            }
            state = state.copyWith(
              devices: sortDevicesBySignalStrength(devices),
            );
          },
          onDone: () {
            if (!_keepScanning || generation != _scanGeneration) {
              state = state.copyWith(scanning: false);
              return;
            }
            _keepScanning = false;
            state = state.copyWith(scanning: false, scanEnded: true);
          },
        );
  }

  /// Cancels an active scan and marks the pass ended (user leave / connect).
  Future<void> stopScan() async {
    await _cancelActiveScan();
    state = state.copyWith(scanning: false, scanEnded: true);
  }

  Future<void> _cancelActiveScan() async {
    _keepScanning = false;
    _scanGeneration++;
    await _scanSubscription?.cancel();
    _scanSubscription = null;
  }
}

bool _passesNameFilter(String bleName, DeviceNameFilterResult filter) {
  if (filter.strict) {
    return filter.allowedNames.contains(bleName);
  }
  if (filter.allowedNames.isEmpty) return true;
  return filter.allowedNames.contains(bleName);
}

/// BLE scan state for [DeviceSearchPage].
final deviceSearchControllerProvider =
    NotifierProvider<DeviceSearchController, DeviceSearchState>(
      DeviceSearchController.new,
    );
```

### 2. `BlePermissionGate.ensureScanPermissions` 全文

```1:44:packages/core/core_permission/lib/src/service/ble_permission_gate.dart
import 'package:core_base/core_base.dart';

import '../model/app_permission.dart';
import 'permission_service.dart';

/// Ensures BLE scan/connect runtime permissions.
abstract final class BlePermissionGate {
  /// Requests bluetooth + location (when in use) if not already granted.
  static Future<Result<void>> ensureScanPermissions(
    PermissionService permissions,
  ) async {
    for (final permission in [
      AppPermission.bluetooth,
      AppPermission.locationWhenInUse,
    ]) {
      final granted = await permissions.isGranted(permission);
      final ok = granted.fold(
        onSuccess: (value) => value,
        onFailure: (_) => false,
      );
      if (ok) {
        continue;
      }

      final requested = await permissions.request(permission);
      final allowed = requested.fold(
        onSuccess: (value) => value,
        onFailure: (error) => error,
      );
      if (allowed is AppError) {
        return Result.failure(allowed);
      }
      if (allowed == false) {
        return const Result.failure(
          AppError(
            code: 'permission.denied',
            message: 'BLE permissions required',
          ),
        );
      }
    }
    return const Result.success(null);
  }
}
```

